-- Search words and short descriptions (owner asked for descriptions so the assistant finds items
-- better, 2026-11-20). Search words are nicknames, misspellings and related words: they're only
-- used to find items and are never shown to customers. Both are editable in the portal menu editor.
-- The live menu was edited in the portal, so data/menu.json isn't re-imported there: descriptions
-- are filled only where an item has none, so nothing the owners wrote is replaced.
ALTER TABLE menu_items ADD COLUMN search_terms TEXT NOT NULL DEFAULT '';

